  function localDate(date = new Date()) {
    const d = new Date(date.getTime() - date.getTimezoneOffset() * 60000);
    return d.toISOString().slice(0, 10);
  }
  function shiftDate(days) { const d = new Date(); d.setDate(d.getDate() + days); return localDate(d); }
  function clone(value) { return JSON.parse(JSON.stringify(value)); }
  function defaultWordLibrary(){const grade=activeChild?.()?.grade||'';if(grade.includes('四'))return '小学四年级上册';if(grade.includes('五'))return '小学五年级上册';if(grade.includes('初'))return '初中核心词汇';if(grade.includes('高'))return '高中核心词汇';return '小学三年级上册';}
  function wordBankForLibrary(library){return WORD_LIBRARIES[library]||WORD_LIBRARIES[defaultWordLibrary()];}
  function journeyWordBank(journey=state.wordJourney){return wordBankForLibrary(journey?.library||defaultWordLibrary());}
  function wordLibraryOptions(selected){return WORD_LIBRARY_NAMES.map(name=>`<option value="${name}" ${name===selected?'selected':''}>${name}</option>`).join('');}
  function freshWordJourney(){return {phase:'select',library:defaultWordLibrary(),selected:[],index:0,assessmentPassed:0};}
  function reviewDueWords(){return state.reviews.filter(word=>['pending','failed'].includes(word.status));}
  function pauseWordJourneyForReview(){const journey=state.wordJourney||freshWordJourney(),canResume=['select','memorize','assess'].includes(journey.phase)&&journey.selected?.length;state.wordJourney={phase:'review',selected:[],index:0,assessmentPassed:0,paused:canResume?clone(journey):null};}
  function resumeWordJourneyAfterReview(){const paused=state.wordJourney?.paused;if(paused&&['select','memorize','assess'].includes(paused.phase)){state.wordJourney=paused;return;}state.wordJourney=freshWordJourney();}
  function blankState(){const value=clone(seed);value.activeChild='';value.mode='parent';value.children=[];value.records=[];value.reviews=[];value.wordJourney=clone(seed.wordJourney);value.quickItems=[];value.baseQuickSettings={};value.quickDisplayOrder=[];value.photos=[];value.audit=[];value.account={nickname:'',avatar:'',exp:0,lastLoginDate:''};value.circlePosts=[];return value;}
