  function loadState(key=activeStorageKey,base=seed){try{const parsed=JSON.parse(localStorage.getItem(key)||'{}'),merged={...clone(base),...parsed};merged.children=Array.isArray(parsed.children)?parsed.children:clone(base.children);merged.records=Array.isArray(parsed.records)?parsed.records:clone(base.records);merged.reviews=Array.isArray(parsed.reviews)?parsed.reviews:clone(base.reviews);merged.wordJourney=parsed.wordJourney||clone(base.wordJourney);merged.quickItems=Array.isArray(parsed.quickItems)?parsed.quickItems:clone(base.quickItems);merged.quickItems.forEach((item,index)=>{item.id=item.id||`custom-${index}-${String(item.name||'item').replace(/\s+/g,'-')}`;});merged.baseQuickSettings=parsed.baseQuickSettings&&typeof parsed.baseQuickSettings==='object'?parsed.baseQuickSettings:{};merged.quickDisplayOrder=Array.isArray(parsed.quickDisplayOrder)?parsed.quickDisplayOrder:[];merged.dashboardMetrics=Array.isArray(parsed.dashboardMetrics)?parsed.dashboardMetrics:clone(base.dashboardMetrics);merged.accountLabels={...clone(base.accountLabels||seed.accountLabels),...(parsed.accountLabels||{})};merged.photos=Array.isArray(parsed.photos)?parsed.photos:clone(base.photos);merged.galleryPlan={...clone(base.galleryPlan||{}),...(parsed.galleryPlan||{})};if(merged.galleryPlan.unlocked&&merged.galleryPlan.plan==='free')merged.galleryPlan.plan='10gb';merged.coursePreferences={...clone(base.coursePreferences||{}),...(parsed.coursePreferences||{})};merged.courseTimer={...clone(base.courseTimer||{}),...(parsed.courseTimer||{})};merged.bridgePreference={...clone(base.bridgePreference||seed.bridgePreference),...(parsed.bridgePreference||{})};merged.bridgeTimer={...clone(base.bridgeTimer||seed.bridgeTimer),...(parsed.bridgeTimer||{})};merged.readingPreference={...clone(base.readingPreference||{}),...(parsed.readingPreference||{})};merged.readingTimer={...clone(base.readingTimer||{}),...(parsed.readingTimer||{})};merged.rules=Array.isArray(parsed.rules)?parsed.rules:clone(base.rules);if(!merged.rules.some(r=>r.name==='课程学习（每小时）'))merged.rules.push(clone(seed.rules.find(r=>r.name==='课程学习（每小时）')));merged.audit=Array.isArray(parsed.audit)?parsed.audit:clone(base.audit);merged.account={...clone(base.account||{}),...(parsed.account||{})};merged.circlePosts=Array.isArray(parsed.circlePosts)?parsed.circlePosts:clone(base.circlePosts||[]);return merged;}catch{return clone(base);}}
