  function openMediaDb(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(new Error('当前浏览器不支持本地相册存储'));return;}const request=indexedDB.open(MEDIA_DB_NAME,1);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(MEDIA_STORE_NAME))db.createObjectStore(MEDIA_STORE_NAME);};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error||new Error('本地相册存储不可用'));});}
  async function putLocalMedia(key,data){if(!key||!data)return;const db=await openMediaDb();await new Promise((resolve,reject)=>{const tx=db.transaction(MEDIA_STORE_NAME,'readwrite');tx.objectStore(MEDIA_STORE_NAME).put(data,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();}
  async function getLocalMedia(key){if(!key)return'';try{const db=await openMediaDb(),data=await new Promise((resolve,reject)=>{const tx=db.transaction(MEDIA_STORE_NAME,'readonly'),request=tx.objectStore(MEDIA_STORE_NAME).get(key);request.onsuccess=()=>resolve(request.result||'');request.onerror=()=>reject(request.error);});db.close();return data;}catch{return'';}}
  function storageSnapshot(){const snapshot=clone(state);snapshot.photos=(snapshot.photos||[]).map(photo=>photo.data?.startsWith('data:')?{...photo,data:'',localMediaKey:photo.localMediaKey||`photo:${photo.id}`} : photo);snapshot.circlePosts=(snapshot.circlePosts||[]).map(post=>post.image?.startsWith('data:')?{...post,image:'',localMediaKey:post.localMediaKey||`circle:${post.id}`} : post);return snapshot;}
  async function migrateAndHydrateLocalMedia(){const writes=[];(state.photos||[]).forEach(photo=>{if(photo.data?.startsWith('data:')){photo.localMediaKey=photo.localMediaKey||`photo:${photo.id}`;writes.push(putLocalMedia(photo.localMediaKey,photo.data));}});(state.circlePosts||[]).forEach(post=>{if(post.image?.startsWith('data:')){post.localMediaKey=post.localMediaKey||`circle:${post.id}`;writes.push(putLocalMedia(post.localMediaKey,post.image));}});await Promise.allSettled(writes);const loads=[];(state.photos||[]).forEach(photo=>{if(!photo.data&&photo.localMediaKey)loads.push(getLocalMedia(photo.localMediaKey).then(data=>{if(data)photo.data=data;}));});(state.circlePosts||[]).forEach(post=>{if(!post.image&&post.localMediaKey)loads.push(getLocalMedia(post.localMediaKey).then(data=>{if(data)post.image=data;}));});await Promise.allSettled(loads);try{localStorage.setItem(activeStorageKey,JSON.stringify(storageSnapshot()));}catch{}renderPhotos();renderCircle();}
