  function pagedItems(items,key,pageSize=PAGE_SIZE){const size=Math.max(1,Number(pageSize)||PAGE_SIZE),pages=Math.max(1,Math.ceil(items.length/size));listPages[key]=Math.min(Math.max(1,Number(listPages[key]||1)),pages);const start=(listPages[key]-1)*size;return{items:items.slice(start,start+size),page:listPages[key],pages,total:items.length,pageSize:size};}
  function renderPagination(containerId,key,result,rerender){const container=$(`#${containerId}`);if(!container)return;if(result.total<=(result.pageSize||PAGE_SIZE)){container.innerHTML='';return;}container.innerHTML=`<button type="button" data-page-prev ${result.page<=1?'disabled':''}>‹ 上一页</button><span>第 ${result.page} / ${result.pages} 页 · 共 ${result.total} 条</span><button type="button" data-page-next ${result.page>=result.pages?'disabled':''}>下一页 ›</button>`;container.querySelector('[data-page-prev]')?.addEventListener('click',()=>{listPages[key]--;rerender();});container.querySelector('[data-page-next]')?.addEventListener('click',()=>{listPages[key]++;rerender();});}

