  const LEGAL_DOCS={
    terms:{title:'小树苗用户协议',html:`<p class="legal-notice">生效日期：${LEGAL_VERSION}。本产品面向孩子的家长或其他监护人，由监护人注册家庭账号并管理孩子模式。</p><h3>一、服务说明</h3><p>小树苗提供家庭成长记录、学习计时、奖罚与消费记账、单词复习、成长相册及相关统计功能。本产品只提供记录工具，不代为保管、发放或结算真实资金；页面中的奖励、罚款、红包和待发放金额均由家庭自行确认和履行。</p><h3>二、账号与监护责任</h3><ul><li>注册人应具备相应民事行为能力，并确认自己有权代表相关未成年人作出授权。</li><li>用户应妥善保管密码和验证码，不得出售、出租或共享账号。</li><li>孩子模式应在监护人指导下使用；涉及奖励确认、处罚、余额调整和相册管理的操作由家长负责。</li></ul><h3>三、内容与使用规范</h3><p>用户应确保上传的姓名、照片、文字及其他内容来源合法，不侵犯他人隐私、肖像、著作权或其他权益。不得利用本服务发布违法、有害、欺凌、侮辱或不适合未成年人的内容，也不得攻击、绕过权限或干扰服务运行。</p><h3>四、相册充值</h3><p>相册免费额度和付费容量以页面展示为准。充值申请须经到账核验后生效，容量权益仅限当前家庭账号使用，不可转让或兑换现金。退款、服务异常与其他争议依法律规定和实际服务情况处理。</p><h3>五、服务调整与中止</h3><p>我们可能因维护、安全、法律要求或产品升级调整功能，并会对重大变化进行合理提示。用户违反本协议或危及未成年人、其他用户及系统安全时，我们可以限制相关功能或停止服务。</p><h3>六、责任边界</h3><p>家庭教育、奖罚决定和第三方学习平台内容由用户自行判断。对不可抗力、第三方服务中断或用户自身操作造成的损失，我们将在法律允许范围内承担责任。</p><h3>七、协议更新与争议</h3><p>协议发生重大变化时将重新提示并依法取得同意。本协议适用中华人民共和国法律；争议应先友好协商，协商不成的，可依法向有管辖权的人民法院提起诉讼。</p>`},
    privacy:{title:'小树苗隐私政策',html:`<p class="legal-notice">生效日期：${LEGAL_VERSION}。未满十四周岁未成年人的个人信息属于敏感个人信息，请由父母或其他监护人阅读并决定是否同意。</p><h3>一、我们处理的信息</h3><ul><li>账号信息：家庭名称、邮箱地址、加密后的认证信息、协议同意时间。</li><li>孩子资料：姓名，以及自愿填写的年级、生日等资料。</li><li>成长数据：学习与家务记录、奖励处罚、积分、金额、复习计划、学习开始和结束时间及持续时长。</li><li>用户内容：成长照片、说明文字、孩子圈内容及头像。</li><li>安全与运行信息：登录状态、操作记录、充值申请、浏览器通知权限及必要的故障信息。</li></ul><h3>二、处理目的</h3><p>上述信息用于创建家庭账本、保存和展示成长记录、计算统计、安排复习提醒、同步相册、验证账号、处理充值以及保障账号和服务安全。非必要资料可不填写，不影响核心记录功能。</p><h3>三、儿童信息保护</h3><p>注册勾选代表监护人对本政策所述处理作出明示同意。我们遵循目的明确、最小必要、安全保障和依法使用原则，不将儿童信息用于定向广告，不公开披露私密相册。监护人可请求查阅、更正、导出或删除孩子信息，也可撤回同意；撤回后部分依赖数据的功能可能无法继续使用。</p><h3>四、存储与期限</h3><p>账号和云端数据由所配置的云服务区域保存，本地体验数据保存在当前浏览器。正式发布前将公示具体存储地点；如发生依法需要单独告知的跨境处理，将另行履行告知、评估和同意义务。数据仅在实现目的所需期限内保存，账号注销或监护人依法提出删除请求后，将在合理期限内删除或匿名化，法律另有规定的除外。</p><h3>五、第三方服务</h3><p>邮箱认证和数据存储目前使用 Supabase，邮件发送使用 Resend；进入国家中小学智慧教育平台后适用该平台自己的规则。我们仅向服务商提供实现相应功能所必要的信息，并要求其采取安全措施。</p><h3>六、安全措施</h3><p>我们采用账号认证、访问控制、私有存储、临时访问链接和操作权限限制等措施。互联网服务无法保证绝对安全；发现泄露风险时将依法采取补救和通知措施。</p><h3>七、您的权利与联系</h3><p>监护人可以申请查阅、复制、更正、补充、删除个人信息，撤回同意或注销账号。隐私问题可联系 privacy@sunout.cn；正式上线前运营者应确保该邮箱可以正常收件并补充运营主体信息。</p><h3>八、政策更新</h3><p>处理目的、信息类型或共享对象发生重大变化时，我们会显著提示，并在依法需要时重新取得监护人同意。</p>`}
  };
  function bindAuth(){
    if(appConfig.SUPABASE_URL&&appConfig.SUPABASE_ANON_KEY&&window.supabase?.createClient)cloudAuth=window.supabase.createClient(appConfig.SUPABASE_URL,appConfig.SUPABASE_ANON_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
    let users=getUsers();if(!users.some(u=>u.username==='demo@sunout.cn')){users.push({username:'demo@sunout.cn',password:'123456',family:'幸福一家',displayName:'林妈妈'});localStorage.setItem(USERS_KEY,JSON.stringify(users));}
    if(cloudAuth){cloudAuth.auth.getSession().then(({data})=>{if(data.session?.user)completeAuth(userProfile(data.session.user),false);});cloudAuth.auth.onAuthStateChange((event,session)=>{if(session?.user&&event==='SIGNED_IN')completeAuth(userProfile(session.user),false);});}else{const session=currentUser();if(session)completeAuth(session,false);}
    $$('[data-auth-tab]').forEach(b=>b.addEventListener('click',()=>switchAuthTab(b.dataset.authTab)));
    $('#demoLogin').addEventListener('click',()=>{const demo=getUsers().find(u=>u.username==='demo@sunout.cn');localStorage.setItem(SESSION_KEY,demo.username);completeAuth(demo,true);});
    $('#loginForm').addEventListener('submit',loginWithEmail);
    $('#sendSignupCode').addEventListener('click',sendSignupCode);
    $('#registerForm').addEventListener('submit',e=>{e.preventDefault();verifySignupCode();});
    $('#forgotPasswordButton').addEventListener('click',openForgotModal);$$('[data-close-forgot]').forEach(b=>b.addEventListener('click',closeForgotModal));$('#forgotModal').addEventListener('click',e=>{if(e.target===e.currentTarget)closeForgotModal();});$('#forgotForm').addEventListener('submit',sendResetCode);$('#resetPasswordButton').addEventListener('click',resetPasswordWithCode);$$('[data-legal]').forEach(button=>button.addEventListener('click',()=>openLegalModal(button.dataset.legal)));$$('[data-close-legal]').forEach(button=>button.addEventListener('click',closeLegalModal));$('#legalModal').addEventListener('click',e=>{if(e.target===e.currentTarget)closeLegalModal();});
    prefillInvitationEmail();
  }
  function openLegalModal(type){const doc=LEGAL_DOCS[type]||LEGAL_DOCS.terms;$('#legalTitle').textContent=doc.title;$('#legalContent').innerHTML=doc.html;$('#legalModal').classList.add('open');$('#legalModal').setAttribute('aria-hidden','false');}
  function closeLegalModal(){$('#legalModal').classList.remove('open');$('#legalModal').setAttribute('aria-hidden','true');}
  async function loginWithEmail(e){e.preventDefault();const email=$('#loginUsername').value.trim().toLowerCase(),password=$('#loginPassword').value;$('#loginError').textContent='';if(email==='demo@sunout.cn'){const user=getUsers().find(u=>u.username===email&&u.password===password);if(!user){$('#loginError').textContent='邮箱或密码不正确';return;}localStorage.setItem(SESSION_KEY,email);completeAuth(user,true);return;}if(!cloudAuthReady()){$('#loginError').textContent='真实邮箱服务尚未配置，请先使用本地体验账号';return;}setBusy($('#loginForm button[type="submit"]'),true,'正在登录…');const{data,error}=await cloudAuth.auth.signInWithPassword({email,password});setBusy($('#loginForm button[type="submit"]'),false,'登录');if(error){$('#loginError').textContent=authError(error);return;}completeAuth(userProfile(data.user),true);}
  async function sendSignupCode(){const form=$('#registerForm');if(!form.reportValidity())return;const family=$('#registerFamily').value.trim(),email=$('#registerUsername').value.trim().toLowerCase(),password=$('#registerPassword').value,confirm=$('#registerConfirm').value;$('#registerError').textContent='';if(!$('#registerAgreement').checked){$('#registerError').textContent='请先阅读并同意用户协议和隐私政策';return;}if(password!==confirm){$('#registerError').textContent='两次输入的密码不一致';return;}if(password.length<6){$('#registerError').textContent='密码至少需要 6 位';return;}const consentedAt=new Date().toISOString();pendingSignup={family,email,password,consentedAt};const button=$('#sendSignupCode');setBusy(button,true,'正在发送…');if(cloudAuthReady()){const redirectTo=appConfig.SITE_URL||window.location.origin;const{data,error}=await cloudAuth.auth.signUp({email,password,options:{emailRedirectTo:redirectTo,data:{family,display_name:email.split('@')[0],guardian_consent:true,terms_version:LEGAL_VERSION,privacy_version:LEGAL_VERSION,consented_at:consentedAt}}});if(error){setBusy(button,false,'发送验证码');$('#registerError').textContent=authError(error);return;}if(data.user&&Array.isArray(data.user.identities)&&data.user.identities.length===0){pendingSignup=null;setBusy(button,false,'发送验证码');$('#registerError').textContent='该邮箱已经注册，请切换到“登录”或使用“忘记密码”';return;}}else toast('本地预览验证码为 123456');startCodeCooldown(button);$('#registerCode').focus();toast(`验证码已请求发送到 ${email}，请检查收件箱和垃圾邮件`);}
