  function empty(text) { return `<div style="padding:35px 0;text-align:center;color:var(--muted)">${text}</div>`; }
  function escapeHtml(v='') { return String(v).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }

  let calendarDate = new Date();
  function renderCalendar() {
    const year = calendarDate.getFullYear(), month = calendarDate.getMonth();
    $('#calendarTitle').textContent = `${year}年 ${month + 1}月`;
    const firstDay = new Date(year, month, 1); const offset = (firstDay.getDay() + 6) % 7;
    const days = new Date(year, month + 1, 0).getDate(); const prevDays = new Date(year, month, 0).getDate();
    const cells = [];
    for (let i=offset-1;i>=0;i--) cells.push({day:prevDays-i,muted:true,date:localDate(new Date(year,month-1,prevDays-i))});
    for (let d=1;d<=days;d++) cells.push({day:d,muted:false,date:localDate(new Date(year,month,d))});
    let next=1; while(cells.length<42) cells.push({day:next,muted:true,date:localDate(new Date(year,month+1,next++))});
    $('#calendarGrid').innerHTML = cells.map(c=>{ const recs=state.records.filter(r=>r.child===state.activeChild&&r.date===c.date); const bad=recs.some(isPenaltyRecord); return `<button class="calendar-day ${c.muted?'muted':''} ${c.date===localDate()?'today':''}" data-date="${c.date}">${c.day}${recs.length?`<i class="record-dot ${bad?'bad':''}"></i>`:''}</button>`; }).join('');
    $$('.calendar-day').forEach(b=>b.addEventListener('click',()=>{ $$('.calendar-day').forEach(x=>x.classList.remove('selected')); b.classList.add('selected'); $('#selectedDateLabel').textContent=formatDateLabel(b.dataset.date);listPages.daily=1;renderTimeline(b.dataset.date); }));
  }
  function formatDateLabel(v){ const d=new Date(`${v}T00:00:00`); return v===localDate()?'今天':`${d.getMonth()+1}月${d.getDate()}日 · ${['周日','周一','周二','周三','周四','周五','周六'][d.getDay()]}`; }

  function bindNavigation() {
    $$('[data-nav]').forEach(el => el.addEventListener('click', e => { e.preventDefault(); showView(el.dataset.nav); }));
    $('#mobileMoreButton')?.addEventListener('click',openMobileMore);$$('[data-close-mobile-more]').forEach(button=>button.addEventListener('click',closeMobileMore));$('#mobileMoreModal')?.addEventListener('click',event=>{if(event.target===event.currentTarget)closeMobileMore();});$$('[data-mobile-destination]').forEach(button=>button.addEventListener('click',()=>{closeMobileMore();showView(button.dataset.mobileDestination);}));$('#mobileDonateButton')?.addEventListener('click',()=>{closeMobileMore();openDonateModal('support');});
    $('#profileButton').addEventListener('click',()=>{showView('settings');const button=$('.settings-nav [data-setting="account"]');button?.click();});
    $('#prevMonth').addEventListener('click',()=>{calendarDate.setMonth(calendarDate.getMonth()-1);renderCalendar()});
    $('#nextMonth').addEventListener('click',()=>{calendarDate.setMonth(calendarDate.getMonth()+1);renderCalendar()});
    $('#recordTypeFilter').addEventListener('change', filterRecordTimeline);
  }
  function showView(name) {
    $$('.view').forEach(v=>v.classList.remove('active')); $(`#${name}View`)?.classList.add('active');
    $$('.nav-item,.mobile-nav [data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav===name));
    const titles={dashboard:'早上好，今天也一起成长',records:'每天的小事，都值得被记住',study:'温故知新，慢慢长大',gallery:'成长的每一刻都值得收藏',circle:'分享孩子的闪光时刻',analytics:'从数据里看见坚持',settings:'家庭成长规则'};
    $('#pageTitle').textContent=titles[name]||titles.dashboard; window.scrollTo({top:0,behavior:'smooth'});
    if(name==='analytics') setTimeout(drawCharts,0);
  }

