  function saveQuickItem(e){e.preventDefault();const name=$('#quickItemName').value.trim(),kind=$('#quickItemKind').value,account=kind==='处罚'?$('#quickItemAccount').value:'pending',amount=Number($('#quickItemAmount').value||0),points=Number($('#quickItemPoints').value||0),duplicateQuick=state.quickItems.some((item,index)=>index!==editingQuickIndex&&item.name===name),baseNames=BASE_QUICK_ITEMS.map(resolvedBaseQuick).filter(item=>item.id!==editingBaseQuickId).map(item=>item.name),originalCustom=editingQuickIndex>=0?state.quickItems[editingQuickIndex]:null,duplicateRule=!editingBaseQuickId&&state.rules.some(rule=>rule.name===name)&&originalCustom?.name!==name;if(duplicateQuick||duplicateRule||baseNames.includes(name)){$('#quickItemError').textContent='这个项目已经存在，请换一个名称';return;}const item={...(originalCustom||{}),id:originalCustom?.id||`custom-${Date.now()}`,name,kind,account,amount,points,hidden:false};if(editingBaseQuickId){const base=BASE_QUICK_ITEMS.find(entry=>entry.id===editingBaseQuickId);state.baseQuickSettings[editingBaseQuickId]={...(state.baseQuickSettings[editingBaseQuickId]||{}),name,kind,account,amount,points,hidden:false};if(base.action==='record'||base.id==='words'){let rule=state.rules.find(entry=>entry.name===base.type);if(rule){rule.amount=amount;rule.points=points;if(base.type!=='消费')rule.kind=kind;}else state.rules.push({name:base.type,amount,points,kind:base.type==='消费'?'消费':kind});}}else if(editingQuickIndex>=0){const previous=state.quickItems[editingQuickIndex],rule=state.rules.find(r=>r.name===previous.name);state.quickItems[editingQuickIndex]=item;if(rule)Object.assign(rule,{name,kind,account,amount,points});else state.rules.push({name,kind,account,amount,points});}else{state.quickItems.push(item);state.rules.push({name,kind,account,amount,points});}ensureQuickDisplayState();save();renderQuickItems();renderRules();closeQuickItemModal();toast(`${name} 已保存`);}
