  function assessWord(pass){ const w=currentReview(); if(!w)return;if(!pass){w.status='failed';toast(`${w.word} 已保留在待复习列表`);const index=state.reviews.indexOf(w);state.reviews.push(state.reviews.splice(index,1)[0]);}else{const intervals=[2,4,8,16];w.lastPassed=localDate();if(w.intervalIndex<intervals.length-1){w.intervalIndex++;w.dueDate=shiftDate(intervals[w.intervalIndex]);w.stage=`第 ${intervals[w.intervalIndex]} 天`;w.status='scheduled';}else w.status='mastered';toast(`${w.word} 复习通过！`);}if(!currentReview()){resumeWordJourneyAfterReview();toast('本次复习已完成，现在可以继续学习新词');}save();renderReviews(); }
  function speakWord(){ const w=currentReview(); if(w)speakText(w.word); }
  function speakText(word){if(!('speechSynthesis'in window)){toast('当前浏览器不支持语音播放');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(word),voices=speechSynthesis.getVoices();utterance.lang='en-US';utterance.rate=.82;utterance.pitch=1;utterance.voice=voices.find(v=>v.lang==='en-US')||voices.find(v=>v.lang.startsWith('en-US'))||voices.find(v=>v.lang.startsWith('en'))||null;speechSynthesis.speak(utterance);}
