  function renderCourseSessions(){if(!$('#courseSessionList'))return;const allSessions=state.records.filter(record=>record.child===state.activeChild&&record.type==='课程学习').sort((a,b)=>String(b.startedAt||`${b.date} ${b.time}`).localeCompare(String(a.startedAt||`${a.date} ${a.time}`))),page=pagedItems(allSessions,'course');$('#courseSessionCount').textContent=`${allSessions.length} 次`;$('#courseSessionList').innerHTML=page.total?page.items.map(record=>{const times=courseRecordTimes(record),start=times.startedAt.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),end=times.endedAt.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),pending=record.status==='pending',actions=pending?(state.mode==='parent'?`<span class="record-action-row"><button class="confirm-record" data-confirm-record="${record.id}">确认并发放</button>${editDeleteActions(record)}</span>`:'<em class="session-status pending">等待家长确认</em>'):recordActionControls(record);return`<article class="course-session-item"><div><strong>${escapeHtml(record.grade||'同步课程')} · ${escapeHtml(record.subject||'学习')}</strong><small>${formatDateLabel(record.date)}</small></div><span>开始 <b>${start}</b></span><span>结束 <b>${end}</b></span><span>时长 <b>${formatStudyDuration(times.durationSeconds)}</b></span>${actions}</article>`;}).join(''):empty('还没有同步课程学习记录，完成一次计时后会显示在这里。');renderPagination('courseSessionPagination','course',page,renderCourseSessions);bindPendingConfirmButtons();}

