  function recordAgeInDays(date){const today=new Date(`${localDate()}T00:00:00`),target=new Date(`${date}T00:00:00`);return Math.floor((today-target)/86400000);}
  function drawScoreChart(){const svg=$('#scoreChart');if(!svg)return;const good=[0,0,0,0],bad=[0,0,0,0],records=state.records.filter(r=>r.child===state.activeChild);records.forEach(r=>{const age=recordAgeInDays(r.date);if(age<0||age>27)return;const bucket=3-Math.floor(age/7);if(isPenaltyRecord(r))bad[bucket]+=Number(r.points||0);else if(!['消费','结算'].includes(r.type))good[bucket]+=Number(r.points||0);});const labels=['3周前','2周前','上周','本周'],axisMax=Math.max(10,Math.ceil(Math.max(...good,...bad)/10)*10),scale=180/axisMax;let html='';[0,.25,.5,.75,1].forEach(ratio=>{const value=Math.round(axisMax*ratio),y=220-value*scale;html+=`<line class="gridline" x1="48" y1="${y}" x2="660" y2="${y}"/><text x="18" y="${y+4}">${value}</text>`});labels.forEach((label,i)=>{const x=95+i*145,goodHeight=good[i]*scale,badHeight=bad[i]*scale;html+=`<rect class="goodbar" x="${x}" y="${220-goodHeight}" width="34" height="${goodHeight}" rx="7"/><rect class="badbar" x="${x+40}" y="${220-badHeight}" width="34" height="${badHeight}" rx="7"/><text x="${x+37}" y="244" text-anchor="middle">${label}</text>`});svg.innerHTML=html;}
  function drawMoneyChart(){const svg=$('#moneyChart');if(!svg)return;const reward=[0,0,0,0,0,0],spend=[0,0,0,0,0,0],penalty=[0,0,0,0,0,0];state.records.filter(r=>r.child===state.activeChild).forEach(r=>{const age=recordAgeInDays(r.date);if(age<0||age>41)return;const bucket=5-Math.floor(age/7),amount=Math.abs(Number(r.amount||0));if(isPenaltyRecord(r))penalty[bucket]+=amount;else if(r.type==='消费')spend[bucket]+=amount;else if(r.type!=='结算'&&Number(r.amount)>0)reward[bucket]+=amount;});const xs=[70,260,450,640,830,1020],axisMax=Math.max(10,Math.ceil(Math.max(...reward,...spend,...penalty)/10)*10),scale=185/axisMax,y=value=>220-value*scale;let html='';[0,.25,.5,.75,1].forEach(ratio=>{const value=Math.round(axisMax*ratio);html+=`<line class="gridline" x1="50" y1="${y(value)}" x2="1040" y2="${y(value)}"/><text x="14" y="${y(value)+4}">¥${value}</text>`});const path=values=>values.map((value,i)=>`${i?'L':'M'}${xs[i]},${y(value)}`).join(' ');html+=`<path class="reward-line" d="${path(reward)}"/><path class="spend-line" d="${path(spend)}"/><path class="penalty-line" d="${path(penalty)}"/>`;[[reward,'var(--forest-2)'],[spend,'var(--warm)'],[penalty,'var(--red)']].forEach(([values,color])=>values.forEach((value,i)=>html+=`<circle cx="${xs[i]}" cy="${y(value)}" r="5" fill="${color}"/>`));['5周前','4周前','3周前','2周前','上周','本周'].forEach((label,i)=>html+=`<text x="${xs[i]}" y="245" text-anchor="middle">${label}</text>`);html+=`<text x="780" y="22" fill="var(--forest-2)">● 奖励</text><text x="855" y="22" fill="var(--warm)">● 消费</text><text x="930" y="22" fill="var(--red)">● 处罚</text>`;svg.innerHTML=html;}

