  async function openInviteParentModal(){if(!(authProfile?.isCloud&&cloudAuthReady())){toast('请先使用正式邮箱账号登录，再邀请共同家长');return;}if(!familyCloudReady){toast('正在连接家庭共享数据…');await initializeFamilyCloud();if(!familyCloudReady){toast(familyCloudHelp());return;}}$('#inviteParentError').textContent='';$('#inviteParentResult').classList.add('hidden');$('#inviteParentForm').classList.remove('hidden');$('#inviteParentEmail').value='';$('#inviteParentModal').classList.add('open');$('#inviteParentModal').setAttribute('aria-hidden','false');setTimeout(()=>$('#inviteParentEmail').focus(),0);}
