  async function createParentInvite(event){event.preventDefault();const email=$('#inviteParentEmail').value.trim().toLowerCase(),errorBox=$('#inviteParentError'),button=$('#createParentInvite');errorBox.textContent='';if(!familyCloudReady||!cloudFamilyId){errorBox.textContent='邀请功能尚未完成数据库升级，请先在 Supabase 执行部署包旁的最新版 supabase-setup.sql。';return;}if(email===(authProfile.email||'').toLowerCase()){errorBox.textContent='不能邀请当前登录邮箱，请填写另一位家长的邮箱。';return;}button.disabled=true;button.textContent='正在生成…';const{data,error}=await cloudAuth.rpc('create_family_invitation_for_family',{p_family_id:cloudFamilyId,invited_email:email});button.disabled=false;button.textContent='生成邀请链接';if(error){errorBox.textContent=authError(error)||'邀请生成失败，请稍后重试';return;}const info=Array.isArray(data)?data[0]:data,origin=location.origin==='null'?'https://sunout.cn':location.origin,link=`${origin}${location.pathname}?invite=${encodeURIComponent(info.invite_code)}&email=${encodeURIComponent(info.invited_email||email)}`;$('#inviteParentLink').value=link;$('#inviteParentForm').classList.add('hidden');$('#inviteParentResult').classList.remove('hidden');await loadFamilyMembers();toast(`“${currentFamilyName()}”的邀请链接已生成，有效期 7 天`);}
  async function copyParentInviteLink(){const input=$('#inviteParentLink'),link=input.value;if(!link)return;try{await navigator.clipboard.writeText(link);}catch{input.select();document.execCommand('copy');}toast('邀请链接已复制');}
