  async function changeAccountPassword(event){event.preventDefault();const current=$('#currentAccountPassword').value,next=$('#newAccountPassword').value,confirmPassword=$('#confirmAccountPassword').value,errorBox=$('#changePasswordError'),button=$('#saveNewPasswordButton');errorBox.textContent='';if(next.length<6){errorBox.textContent='新密码至少需要 6 位';return;}if(next===current){errorBox.textContent='新密码不能与当前密码相同';return;}if(next!==confirmPassword){errorBox.textContent='两次输入的新密码不一致';return;}setBusy(button,true,'正在修改…');try{if(authProfile?.isCloud&&cloudAuthReady()){const verified=await cloudAuth.auth.signInWithPassword({email:authProfile.email,password:current});if(verified.error){errorBox.textContent='当前密码不正确';return;}const updated=await cloudAuth.auth.updateUser({password:next});if(updated.error){errorBox.textContent=authError(updated.error);return;}}else{const users=getUsers(),user=users.find(item=>item.username===authProfile?.username);if(!user||user.password!==current){errorBox.textContent='当前密码不正确';return;}user.password=next;localStorage.setItem(USERS_KEY,JSON.stringify(users));}state.audit.unshift({who:authProfile?.displayName||'家长',action:'修改了登录密码',detail:'账户密码已安全更新',time:'刚刚'});save();closeChangePasswordModal();toast('登录密码已修改，请妥善保管新密码');}catch(error){errorBox.textContent=authError(error);}finally{setBusy(button,false,'确认修改');}}
