  async function uploadAccountAvatar(){const file=$('#accountAvatarFile').files[0];if(!file)return;if(file.size>10*1024*1024){toast('请选择 10MB 以内的头像');return;}const button=$('#accountAvatarButton');button.disabled=true;try{let avatar='';if(authProfile?.isCloud&&cloudAuthReady()&&authProfile.userId){const ext=(file.name.split('.').pop()||'jpg').toLowerCase(),path=`${authProfile.userId}/avatar-${Date.now()}.${ext}`,{error}=await cloudAuth.storage.from('avatars').upload(path,file,{cacheControl:'3600',upsert:false,contentType:file.type});if(!error){avatar=await signedMediaUrl('avatars',path);state.account.avatarPath=path;await cloudAuth.from('profiles').update({avatar_url:path,updated_at:new Date().toISOString()}).eq('id',authProfile.userId);}}if(!avatar)avatar=await compressPhoto(file);state.account.avatar=avatar;save();renderAccountProfile();renderFamilyMembers();renderCircle();toast(avatar.startsWith('data:')?'头像已保存到本机；配置云存储后会跨设备同步':'头像已更新');}catch{toast('头像处理失败，请换一张照片重试');}finally{button.disabled=false;$('#accountAvatarFile').value='';}}
